// First admin for apps in this repo (Tumbler, Coffer). The server accepts POST /api/setup only while it has no users and only with
// ADMIN_SETUP_TOKEN (generated by the installer at deploy). Keys are derived here, so the server
// never sees the password or the vault key. The recovery key is printed once.

import { generateVaultKey, makeAccountMaterial } from "@cfsa/crypto";
import type { LocalApp } from "./install-local.ts";
import { ClaimError } from "./nodewarden.ts";

function originOf(url: string): string {
	const u = new URL(url);
	if (u.protocol !== "https:" && !["localhost", "127.0.0.1", "[::1]"].includes(u.hostname)) {
		throw new ClaimError("Refusing to send credentials over plain HTTP to a non-local host");
	}
	return u.origin;
}

async function request(url: string, init?: RequestInit): Promise<Response> {
	try {
		return await fetch(url, init);
	} catch (e) {
		throw new ClaimError(`Cannot reach ${new URL(url).origin}: ${e instanceof Error ? e.message : String(e)}`);
	}
}

export async function assertSetupNeeded(app: LocalApp, url: string): Promise<void> {
	const res = await request(`${originOf(url)}/api/setup`);
	if (!res.ok) throw new ClaimError(`GET /api/setup failed (${res.status}). Are migrations applied?`);
	const s = (await res.json()) as { needed: boolean; tokenConfigured: boolean };
	if (!s.tokenConfigured) throw new ClaimError("ADMIN_SETUP_TOKEN is not set on the Worker");
	if (!s.needed) throw new ClaimError(`This ${app.name} server already has accounts. Invite more users from ${app.inviteHint}.`);
}

const USERNAME = /^[a-z0-9](?:[a-z0-9._-]{1,62}[a-z0-9])$/;

export function normalizeUsername(input: string): string {
	const u = input.trim().toLowerCase();
	if (!USERNAME.test(u)) throw new ClaimError("Username: 3–64 characters, a–z, 0–9, '.', '_' or '-'");
	return u;
}

export async function setupAdmin(app: LocalApp, args: {
	url: string;
	setupToken: string;
	username: string;
	password: string;
}): Promise<{ url: string; username: string; recoveryKey: string }> {
	const origin = originOf(args.url);
	const username = normalizeUsername(args.username);
	const vaultKey = generateVaultKey();
	const { material, recoveryKey } = await makeAccountMaterial(args.password, vaultKey);
	vaultKey.fill(0);
	const res = await request(`${origin}/api/setup`, {
		method: "POST",
		headers: { "Content-Type": "application/json", Origin: origin },
		body: JSON.stringify({ setupToken: args.setupToken, username, ...material }),
	});
	if (!res.ok) {
		const body = (await res.json().catch(() => ({}))) as { error?: string; message?: string };
		if (body.error === "already_set_up") throw new ClaimError(`This ${app.name} server already has accounts.`);
		if (body.error === "invalid_setup_token") throw new ClaimError("Wrong ADMIN_SETUP_TOKEN.");
		throw new ClaimError(`Setup failed (${res.status}): ${body.message ?? body.error ?? "unknown error"}`);
	}
	return { url: origin, username, recoveryKey };
}

/** The only place the recovery key is printed. */
export function printAdminSummary(app: LocalApp, r: { url: string; username: string; recoveryKey: string }): void {
	const line = "─".repeat(64);
	console.log(`
${line}
  ${app.name} admin account created

  URL           ${r.url}
  Username      ${r.username}
  Password      (the one you entered; not shown or stored)
  Recovery key  ${r.recoveryKey}

  ⚠  The recovery key is shown ONCE. It is the only way back in if
     you forget the password. Save it in a password manager (e.g.
     Bitwarden, Proton Pass) or write it down and keep it offline.

  Next: ${app.id === "tumbler" ? 'open the URL, choose "Sign in to sync",' : "open the URL and sign in,"}
  then turn on two-step login and invite users from
  ${app.inviteHint}.
${line}
`);
}
